            agent,
            model: profile ? defaultModelForProfile(profile) : '',
            permissionMode: profile && supportsPermissionMode(profile) ? DEFAULT_PERMISSION_MODE : '',
            thinkingLevel: 'none',
        }
        settingsStore.setSettings(nextSettings, changedWhileWaiting)
        handleCloseModelMenu()
    }

